{
  "version": "Notebook/1.0",
  "items": [
    {
      "type": 9,
      "content": {
        "version": "KqlParameterItem/1.0",
        "crossComponentResources": [
          "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
        ],
        "parameters": [
          {
            "id": "8b4e0e32-1f2a-4e15-8f83-011a1b5a61db",
            "version": "KqlParameterItem/1.0",
            "name": "TimeRange",
            "label": "Time Range",
            "type": 4,
            "isRequired": true,
            "value": { "durationMs": 3600000 },
            "typeSettings": {
              "selectableValues": [
                { "durationMs": 300000 },
                { "durationMs": 900000 },
                { "durationMs": 1800000 },
                { "durationMs": 3600000 },
                { "durationMs": 14400000 },
                { "durationMs": 43200000 },
                { "durationMs": 86400000 }
              ]
            }
          },
          {
            "id": "9c2a1f51-3e8b-4a22-9d04-122b2c6a72ec",
            "version": "KqlParameterItem/1.0",
            "name": "Granularity",
            "label": "Chart Granularity",
            "type": 2,
            "isRequired": true,
            "value": "5m",
            "jsonData": "[{\"value\":\"1m\",\"label\":\"1 minute\"},{\"value\":\"5m\",\"label\":\"5 minutes\"},{\"value\":\"15m\",\"label\":\"15 minutes\"},{\"value\":\"30m\",\"label\":\"30 minutes\"},{\"value\":\"1h\",\"label\":\"1 hour\"}]",
            "typeSettings": {
              "additionalResourceOptions": [],
              "showDefault": false
            }
          }
        ],
        "style": "above",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces"
      },
      "name": "parameters"
    },

    {
      "type": 1,
      "content": {
        "json": "# AppGW → APIM → Foundry Backend Routing Report\n\nFull traffic flow from **Application Gateway WAF v2** through **APIM** to **Azure AI Foundry** backends. Use this workbook to:\n- See when the circuit breaker switches traffic between **Primary (East US)** and **Secondary (West US)** Foundry\n- Identify **why** a switch happened (429 throttling, 5xx errors, retry failover)\n- Compare end-to-end latency by backend and layer\n\n> **Circuit breaker policy** (from `circuit-breaker-multi-region.xml`): trips after **5 failures** (429 or ≥500) to primary within a 5-minute window. Resets automatically on successful responses."
      },
      "name": "text-header"
    },

    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "union\n  (ApiManagementGatewayLogs | where TimeGenerated {TimeRange} | summarize Value=count() | extend Metric=\"Total Requests\", Sub=\"through APIM\"),\n  (ApiManagementGatewayLogs | where TimeGenerated {TimeRange} | where BackendUrl has \"primary\" | summarize Value=count() | extend Metric=\"Primary Backend\", Sub=\"Foundry East US\"),\n  (ApiManagementGatewayLogs | where TimeGenerated {TimeRange} | where BackendUrl has \"secondary\" | summarize Value=count() | extend Metric=\"Secondary Backend\", Sub=\"Foundry West US (failover)\"),\n  (ApiManagementGatewayLogs | where TimeGenerated {TimeRange} | where isnotempty(BackendUrl) and (ResponseCode >= 400 or BackendResponseCode >= 400) | summarize Value=count() | extend Metric=\"Backend Errors\", Sub=\"4xx / 5xx\")\n| project Metric, Value, Sub",
        "size": 4,
        "title": "Traffic Summary",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
        ],
        "visualization": "tiles",
        "tileSettings": {
          "titleContent": { "columnMatch": "Metric", "formatter": 1 },
          "leftContent":  { "columnMatch": "Value",  "formatter": 12, "formatOptions": { "palette": "auto" } },
          "secondaryContent": { "columnMatch": "Sub", "formatter": 1 },
          "showBorder": true,
          "size": "auto"
        }
      },
      "name": "query-kpis"
    },

    {
      "type": 1,
      "content": {
        "json": "---\n## Backend Routing Timeline\nStacked area showing how many requests went to each backend per time interval. A solid block of **Secondary** traffic means the circuit breaker was open and all requests were failing over."
      },
      "name": "text-s1"
    },

    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ApiManagementGatewayLogs\n| where TimeGenerated {TimeRange}\n| extend Backend = case(\n    BackendUrl has \"primary\",   \"Primary (East US)\",\n    BackendUrl has \"secondary\", \"Secondary (West US)\",\n    isempty(BackendUrl),        \"No Backend (APIM-rejected)\",\n    \"Other\")\n| summarize Requests=count() by bin(TimeGenerated, {Granularity}), Backend",
        "size": 0,
        "title": "Requests per Backend",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
        ],
        "visualization": "areachart",
        "chartSettings": {
          "seriesLabelSettings": [
            { "seriesName": "Primary (East US)",        "color": "green" },
            { "seriesName": "Secondary (West US)",       "color": "orange" },
            { "seriesName": "No Backend (APIM-rejected)", "color": "blue" }
          ]
        }
      },
      "name": "query-routing-timeline"
    },

    {
      "type": 1,
      "content": {
        "json": "---\n## Backend Switch Events\nEach row is a point where traffic shifted to a different backend than the previous request. **Failover (primary → secondary)** means the circuit breaker tripped or a mid-request retry succeeded on secondary. **Recovery (secondary → primary)** means the circuit breaker reset.\n\n> Tip: sort by `TimeGenerated` and look at `LastErrorReason` / `BackendResponseCode` on the preceding rows in the detail table below to find what triggered the switch."
      },
      "name": "text-s2"
    },

    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ApiManagementGatewayLogs\n| where TimeGenerated {TimeRange}\n| where isnotempty(BackendUrl)\n| extend BackendRegion = iff(BackendUrl has \"primary\", \"primary\", iff(BackendUrl has \"secondary\", \"secondary\", \"other\"))\n| sort by TimeGenerated asc\n| extend PrevRegion = prev(BackendRegion, 1, \"\")\n| where BackendRegion != PrevRegion and PrevRegion != \"\"\n| extend Direction = case(\n    PrevRegion == \"primary\"   and BackendRegion == \"secondary\", \"🔴 Failover: primary → secondary\",\n    PrevRegion == \"secondary\" and BackendRegion == \"primary\",   \"🟢 Recovery: secondary → primary\",\n    strcat(PrevRegion, \" → \", BackendRegion))\n| project\n    TimeGenerated,\n    Direction,\n    ResponseCode,\n    BackendResponseCode,\n    ['TotalTime (ms)']   = TotalTime,\n    ['BackendTime (ms)'] = BackendTime,\n    LastErrorReason,\n    LastErrorMessage,\n    ApimSubscriptionId\n| order by TimeGenerated desc",
        "size": 0,
        "title": "Backend Switch Events",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
        ],
        "visualization": "table",
        "gridSettings": {
          "filter": true,
          "sortBy": [{ "itemKey": "TimeGenerated", "sortOrder": 2 }],
          "formatters": [
            {
              "columnMatch": "ResponseCode",
              "formatter": 18,
              "formatOptions": {
                "thresholdsOptions": "icons",
                "thresholdsGrid": [
                  { "operator": "<",       "thresholdValue": "300",  "representation": "success", "text": "{0}{1}" },
                  { "operator": "<",       "thresholdValue": "500",  "representation": "warning", "text": "{0}{1}" },
                  { "operator": "Default", "thresholdValue": null,   "representation": "error",   "text": "{0}{1}" }
                ]
              }
            },
            {
              "columnMatch": "BackendResponseCode",
              "formatter": 18,
              "formatOptions": {
                "thresholdsOptions": "icons",
                "thresholdsGrid": [
                  { "operator": "<",       "thresholdValue": "300",  "representation": "success", "text": "{0}{1}" },
                  { "operator": "<",       "thresholdValue": "500",  "representation": "warning", "text": "{0}{1}" },
                  { "operator": "Default", "thresholdValue": null,   "representation": "error",   "text": "{0}{1}" }
                ]
              }
            },
            {
              "columnMatch": "TotalTime (ms)",
              "formatter": 8,
              "formatOptions": { "palette": "redGreen", "max": 3000 },
              "numberFormat": { "unit": 23, "options": { "style": "decimal", "maximumFractionDigits": 0 } }
            },
            {
              "columnMatch": "BackendTime (ms)",
              "formatter": 8,
              "formatOptions": { "palette": "yellowOrangeRed", "max": 2000 },
              "numberFormat": { "unit": 23, "options": { "style": "decimal", "maximumFractionDigits": 0 } }
            }
          ]
        }
      },
      "name": "query-switch-events"
    },

    {
      "type": 1,
      "content": {
        "json": "---\n## Circuit Breaker Pressure\nLeft — **failures per minute to the primary backend** (bars exceed threshold = circuit breaker trips).  Right — **error rate %** per backend over the selected window."
      },
      "name": "text-s3"
    },

    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ApiManagementGatewayLogs\n| where TimeGenerated {TimeRange}\n| where BackendUrl has \"primary\"\n| where ResponseCode >= 400 or BackendResponseCode >= 400\n| summarize FailuresToPrimary=count() by bin(TimeGenerated, 1m)\n| extend CircuitBreakerThreshold = 5\n| order by TimeGenerated asc",
        "size": 1,
        "title": "Primary Backend Failures per Minute  (circuit breaker threshold = 5)",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
        ],
        "visualization": "barchart",
        "chartSettings": {
          "seriesLabelSettings": [
            { "seriesName": "FailuresToPrimary",       "color": "orange" },
            { "seriesName": "CircuitBreakerThreshold", "color": "red"    }
          ]
        }
      },
      "customWidth": "50",
      "name": "query-cb-pressure"
    },

    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ApiManagementGatewayLogs\n| where TimeGenerated {TimeRange}\n| where isnotempty(BackendUrl)\n| extend BackendRegion = iff(BackendUrl has \"primary\", \"Primary (East US)\", iff(BackendUrl has \"secondary\", \"Secondary (West US)\", \"Other\"))\n| summarize Total=count(), Errors=countif(ResponseCode >= 400 or BackendResponseCode >= 400) by bin(TimeGenerated, {Granularity}), BackendRegion\n| extend ErrorPct = round(100.0 * Errors / Total, 1)\n| project TimeGenerated, BackendRegion, ErrorPct",
        "size": 1,
        "title": "Error Rate % by Backend",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
        ],
        "visualization": "linechart",
        "chartSettings": {
          "seriesLabelSettings": [
            { "seriesName": "Primary (East US)",  "color": "green"  },
            { "seriesName": "Secondary (West US)", "color": "orange" }
          ]
        }
      },
      "customWidth": "50",
      "name": "query-error-rate"
    },

    {
      "type": 1,
      "content": {
        "json": "---\n## End-to-End Latency Chain\nThe three latency layers:\n- **AppGW P50 (ms)** — total time the client experiences (AppGW `TimeTaken`, includes WAF inspection + APIM + Foundry)\n- **APIM Total P50 (ms)** — APIM's `TotalTime` (policy execution + Foundry round-trip)\n- **Backend P50 (ms)** — APIM's `BackendTime` (pure Foundry response time)\n\n**AppGW overhead** = AppGW P50 − APIM P50 (WAF + AppGW routing). **APIM policy overhead** = APIM Total − Backend. A spike in Backend with flat APIM overhead → Foundry is the bottleneck. Flat backend with rising APIM overhead → APIM policy issue."
      },
      "name": "text-s4"
    },

    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let apim = ApiManagementGatewayLogs\n| where TimeGenerated {TimeRange}\n| where isnotempty(BackendUrl)\n| summarize\n    ['APIM Total P50 (ms)']   = percentile(TotalTime,   50),\n    ['APIM Total P90 (ms)']   = percentile(TotalTime,   90),\n    ['Backend (Foundry) P50 (ms)'] = percentile(BackendTime, 50),\n    ['Backend (Foundry) P90 (ms)'] = percentile(BackendTime, 90)\n  by bin(TimeGenerated, {Granularity});\nlet agw = AGWAccessLogs\n| where TimeGenerated {TimeRange}\n| summarize\n    ['AppGW P50 (ms)'] = round(percentile(TimeTaken, 50) * 1000, 0),\n    ['AppGW P90 (ms)'] = round(percentile(TimeTaken, 90) * 1000, 0)\n  by bin(TimeGenerated, {Granularity});\nagw\n| join kind=leftouter (apim) on TimeGenerated\n| project-away TimeGenerated1\n| order by TimeGenerated asc",
        "size": 0,
        "title": "Full Chain Latency: AppGW → APIM → Foundry  (P50 and P90, ms)",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
        ],
        "visualization": "linechart",
        "chartSettings": {
          "seriesLabelSettings": [
            { "seriesName": "AppGW P50 (ms)",              "color": "purple" },
            { "seriesName": "AppGW P90 (ms)",              "color": "lightPurple" },
            { "seriesName": "APIM Total P50 (ms)",         "color": "blue" },
            { "seriesName": "APIM Total P90 (ms)",         "color": "lightBlue" },
            { "seriesName": "Backend (Foundry) P50 (ms)",  "color": "green" },
            { "seriesName": "Backend (Foundry) P90 (ms)",  "color": "lightGreen" }
          ]
        }
      },
      "name": "query-chain-latency"
    },

    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ApiManagementGatewayLogs\n| where TimeGenerated {TimeRange}\n| where isnotempty(BackendUrl)\n| extend BackendRegion = iff(BackendUrl has \"primary\", \"Primary (East US)\", iff(BackendUrl has \"secondary\", \"Secondary (West US)\", \"Other\"))\n| summarize\n    ['P50 Total (ms)']   = percentile(TotalTime,   50),\n    ['P90 Total (ms)']   = percentile(TotalTime,   90),\n    ['P50 Backend (ms)'] = percentile(BackendTime, 50),\n    ['P90 Backend (ms)'] = percentile(BackendTime, 90)\n  by bin(TimeGenerated, {Granularity}), BackendRegion",
        "size": 0,
        "title": "APIM Latency by Backend — P50 / P90 (ms)",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
        ],
        "visualization": "linechart",
        "chartSettings": {
          "seriesLabelSettings": [
            { "seriesName": "Primary (East US)",  "color": "green"  },
            { "seriesName": "Secondary (West US)", "color": "orange" }
          ]
        }
      },
      "name": "query-latency-by-backend"
    },

    {
      "type": 1,
      "content": {
        "json": "---\n## Full Request Chain Detail\nIndividual requests with full routing information. `CallerIpAddress` is the AppGW internal IP (`10.100.1.x`). `BackendResponseCode` is what Foundry returned before any APIM transformation; `ResponseCode` is what the client received. Use `CorrelationId` to trace a specific request across APIM trace logs.\n\n> Filter the table by `BackendRegion` or `ResponseCode` to isolate failover requests."
      },
      "name": "text-s5"
    },

    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "ApiManagementGatewayLogs\n| where TimeGenerated {TimeRange}\n| where isnotempty(BackendUrl)\n| extend BackendRegion = iff(BackendUrl has \"primary\", \"Primary (East US)\", iff(BackendUrl has \"secondary\", \"Secondary (West US)\", \"Other\"))\n| extend FailoverOccurred = iff(BackendUrl has \"secondary\" and BackendResponseCode == 200, \"Yes\", \"\")\n| project\n    TimeGenerated,\n    BackendRegion,\n    FailoverOccurred,\n    ApimSubscriptionId,\n    ResponseCode,\n    BackendResponseCode,\n    ['TotalTime (ms)']   = TotalTime,\n    ['BackendTime (ms)'] = BackendTime,\n    IsRequestSuccess,\n    LastErrorReason,\n    LastErrorMessage,\n    CallerIpAddress,\n    CorrelationId\n| order by TimeGenerated desc\n| limit 500",
        "size": 0,
        "title": "Full Request Chain — AppGW → APIM → Foundry (latest 500 requests)",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
        ],
        "visualization": "table",
        "gridSettings": {
          "filter": true,
          "sortBy": [{ "itemKey": "TimeGenerated", "sortOrder": 2 }],
          "formatters": [
            {
              "columnMatch": "BackendRegion",
              "formatter": 18,
              "formatOptions": {
                "thresholdsOptions": "icons",
                "thresholdsGrid": [
                  { "operator": "==",      "thresholdValue": "Primary (East US)",  "representation": "success", "text": "{0}{1}" },
                  { "operator": "Default", "thresholdValue": null,                 "representation": "warning", "text": "{0}{1}" }
                ]
              }
            },
            {
              "columnMatch": "ResponseCode",
              "formatter": 18,
              "formatOptions": {
                "thresholdsOptions": "icons",
                "thresholdsGrid": [
                  { "operator": "<",       "thresholdValue": "300",  "representation": "success", "text": "{0}{1}" },
                  { "operator": "<",       "thresholdValue": "500",  "representation": "warning", "text": "{0}{1}" },
                  { "operator": "Default", "thresholdValue": null,   "representation": "error",   "text": "{0}{1}" }
                ]
              }
            },
            {
              "columnMatch": "BackendResponseCode",
              "formatter": 18,
              "formatOptions": {
                "thresholdsOptions": "icons",
                "thresholdsGrid": [
                  { "operator": "<",       "thresholdValue": "300",  "representation": "success", "text": "{0}{1}" },
                  { "operator": "<",       "thresholdValue": "500",  "representation": "warning", "text": "{0}{1}" },
                  { "operator": "Default", "thresholdValue": null,   "representation": "error",   "text": "{0}{1}" }
                ]
              }
            },
            {
              "columnMatch": "TotalTime (ms)",
              "formatter": 8,
              "formatOptions": { "palette": "coldHot", "max": 3000 },
              "numberFormat": { "unit": 23, "options": { "style": "decimal", "maximumFractionDigits": 0 } }
            },
            {
              "columnMatch": "BackendTime (ms)",
              "formatter": 8,
              "formatOptions": { "palette": "yellowOrangeRed", "max": 2000 },
              "numberFormat": { "unit": 23, "options": { "style": "decimal", "maximumFractionDigits": 0 } }
            }
          ]
        }
      },
      "name": "query-chain-detail"
    }
  ],
  "defaultResourceIds": [
    "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
  ],
  "$schema": "https://github.com/Microsoft/Application-Insights-Workbooks/blob/master/schema/workbook.json"
}

