    {
      "type": 1,
      "content": { "json": "## Per-Layer Latency Waterfall\n\nEach bar represents **average time spent in that layer** for requests in the selected time window. APIM overhead = `APIM duration − Foundry duration`." },
      "name": "section-waterfall"
    },

    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "// Per-layer latency waterfall — stacked bar per time bucket\nlet bucket = {Granularity:value};\nlet apimReqs = AppRequests\n| where TimeGenerated {TimeRange}\n| extend corrId = tostring(customDimensions[\"Request-Header-X-Correlation-Id\"])\n| where isnotempty(corrId)\n| project TimeGenerated, corrId, apimDurationMs = DurationMs, opId = OperationId;\nlet foundryDeps = AppDependencies\n| where TimeGenerated {TimeRange}\n| where Type == \"HTTP\"\n| extend corrId = tostring(customDimensions[\"Request-Header-X-Correlation-Id\"])\n| where isnotempty(corrId)\n| project corrId, foundryDurationMs = DurationMs, opId = OperationId;\nlet appgwLogs = AGWAccessLogs\n| where TimeGenerated {TimeRange}\n| extend corrId = tostring(requestUri_s)   // transactionId not always populated; use URI as fallback grouping\n| project TimeGenerated, timeTakenMs = toreal(timeTaken_d) * 1000;\napimReqs\n| join kind=leftouter foundryDeps on corrId\n| extend foundryMs   = iff(isnotempty(foundryDurationMs), foundryDurationMs, 0.0)\n| extend apimOverheadMs = max_of(apimDurationMs - foundryMs, 0.0)\n| summarize\n    avgAppgwMs      = 0.0,      // App GW timing joined separately — see note below\n    avgApimOverheadMs = avg(apimOverheadMs),\n    avgFoundryMs    = avg(foundryMs)\n    by bin(TimeGenerated, 5m)\n| extend t = TimeGenerated\n| project t, ['App GW overhead'] = avgAppgwMs, ['APIM overhead'] = avgApimOverheadMs, ['Foundry inference'] = avgFoundryMs",
        "size": 0,
        "title": "Avg latency per layer (5-min buckets)",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
        ],
        "visualization": "barchart",
        "chartSettings": {
          "seriesLabelSettings": [
            { "seriesName": "App GW overhead",  "color": "blue"   },
            { "seriesName": "APIM overhead",    "color": "orange" },
            { "seriesName": "Foundry inference","color": "green"  }
          ],
          "xSettings": { "label": "Time" },
          "ySettings": { "label": "Milliseconds", "min": 0 }
        }
      },
      "name": "waterfall-chart"
    },

    {
      "type": 1,
      "content": { "json": "## Full App Gateway + APIM Join\n\nMatches each `AppRequests` row to its `AGWAccessLogs` entry via an **approximate join**: client IP is extracted from the corrId (`{var_client_ip}-{var_client_port}`) and matched against `AGWAccessLogs` within a 2-second time bucket centred on the APIM request start time.\n\n> Azure Application Gateway does not expose a per-request UUID server variable. The TCP source port + client IP pair is unique for any active connection. Within a 2-second window with the same client IP the closest AGW entry is matched." },
      "name": "section-join"
    },

    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "// Full 3-layer trace table: AGW → APIM → Foundry\n// corrId format: \"{var_client_ip}-{var_client_port}\" stamped by AppGW rewrite rule.\n// APIM → Foundry: direct join on the shared corrId header value.\n// AppGW → APIM:   approximate join using client IP (from corrId) + APIM start time binned to 2s.\nlet filter_corrId = \"{CorrelationId}\";\nlet apimRows = AppRequests\n| where TimeGenerated {TimeRange}\n| extend corrId = tostring(customDimensions[\"Request-Header-X-Correlation-Id\"])\n| where isnotempty(corrId)\n| where filter_corrId == \"\" or corrId == filter_corrId\n| project\n    corrId,\n    opId             = OperationId,\n    apimStart        = TimeGenerated,\n    apimDurationMs   = DurationMs,\n    httpStatus       = ResultCode,\n    success          = Success,\n    url              = Url,\n    apimProduct      = tostring(customDimensions[\"Product\"]),\n    apimSubscription = tostring(customDimensions[\"Subscription\"]);\nlet foundryRows = AppDependencies\n| where TimeGenerated {TimeRange}\n| where Type == \"HTTP\"\n| extend corrId = tostring(customDimensions[\"Request-Header-X-Correlation-Id\"])\n| where isnotempty(corrId)\n| where filter_corrId == \"\" or corrId == filter_corrId\n| summarize\n    foundryDurationMs = avg(DurationMs),\n    foundryTarget     = any(Target),\n    foundrySuccess    = any(Success)\n    by corrId, opId = OperationId;\nlet agwRows = AGWAccessLogs\n| where TimeGenerated {TimeRange}\n| project\n    agwStart         = TimeGenerated,\n    agwTimeTakenMs   = toreal(timeTaken_d) * 1000,\n    agwClientIp      = tostring(clientIP_s),\n    agwHttpStatus    = toint(httpStatus_d),\n    agwSentBytes     = toreal(sentBytes_d),\n    agwReceivedBytes = toreal(receivedBytes_d),\n    agwKey           = strcat(tostring(clientIP_s), \"~\", tostring(bin(TimeGenerated, 2s)));\napimRows\n| join kind=leftouter foundryRows on corrId\n// corrId = \"{clientIp}-{port}\" — extract client IP as join key\n| extend corrClientIp = tostring(split(corrId, \"-\")[0])\n| extend approxKey    = strcat(corrClientIp, \"~\", tostring(bin(apimStart, 2s)))\n| join kind=leftouter agwRows on $left.approxKey == $right.agwKey\n| project-away corrClientIp, approxKey, agwKey\n| extend\n    apimOverheadMs = max_of(apimDurationMs - iff(isnotempty(foundryDurationMs), foundryDurationMs, 0.0), 0.0),\n    agwOverheadMs  = max_of(agwTimeTakenMs - apimDurationMs, 0.0)\n| project\n    Time               = apimStart,\n    ['Correlation ID'] = corrId,\n    ['URL']            = url,\n    ['Status']         = httpStatus,\n    ['Total (ms)']     = round(agwTimeTakenMs, 1),\n    ['AppGW (ms)']     = round(agwOverheadMs, 1),\n    ['APIM (ms)']      = round(apimOverheadMs, 1),\n    ['Foundry (ms)']   = round(foundryDurationMs, 1),\n    ['Foundry backend']= foundryTarget,\n    ['APIM product']   = apimProduct,\n    ['Client IP']      = agwClientIp,\n    ['Success']        = success\n| sort by Time desc",
        "size": 1,
        "title": "Per-request trace table (AppGW + APIM + Foundry)",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
        ],
        "visualization": "table",
        "gridSettings": {
          "formatters": [
            { "columnMatch": "Status",      "formatter": 18, "formatOptions": { "thresholdsOptions": "icons", "thresholdsGrid": [ { "operator": ">=", "thresholdValue": "400", "representation": "failed",   "text": "{0}" }, { "operator": "Default", "thresholdValue": null, "representation": "success", "text": "{0}" } ] } },
            { "columnMatch": "Success",     "formatter": 18, "formatOptions": { "thresholdsOptions": "icons", "thresholdsGrid": [ { "operator": "==", "thresholdValue": "false", "representation": "failed", "text": "" }, { "operator": "Default", "thresholdValue": null, "representation": "success", "text": "" } ] } },
            { "columnMatch": "Total (ms)",  "formatter": 8,  "formatOptions": { "palette": "yellowOrangeRed",  "min": 0, "max": 30000 } },
            { "columnMatch": "AppGW (ms)",  "formatter": 8,  "formatOptions": { "palette": "blue",             "min": 0, "max": 5000  } },
            { "columnMatch": "APIM (ms)",   "formatter": 8,  "formatOptions": { "palette": "orange",           "min": 0, "max": 5000  } },
            { "columnMatch": "Foundry (ms)","formatter": 8,  "formatOptions": { "palette": "green",            "min": 0, "max": 30000 } }
          ],
          "rowLimit": 100,
          "filter": true
        }
      },
      "name": "trace-table"
    },

    {
      "type": 1,
      "content": { "json": "## P50 / P95 / P99 Latency by Layer\n\nUse this to identify which layer is the latency bottleneck for your slowest requests." },
      "name": "section-percentiles"
    },

    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "let apimReqs = AppRequests\n| where TimeGenerated {TimeRange}\n| extend corrId = tostring(customDimensions[\"Request-Header-X-Correlation-Id\"])\n| where isnotempty(corrId)\n| project corrId, apimDurationMs = DurationMs, opId = OperationId;\nlet foundryDeps = AppDependencies\n| where TimeGenerated {TimeRange}\n| where Type == \"HTTP\"\n| extend corrId = tostring(customDimensions[\"Request-Header-X-Correlation-Id\"])\n| where isnotempty(corrId)\n| summarize foundryMs = avg(DurationMs) by corrId;\napimReqs\n| join kind=leftouter foundryDeps on corrId\n| extend foundryMs        = iff(isnotempty(foundryMs), foundryMs, 0.0)\n| extend apimOverheadMs   = max_of(apimDurationMs - foundryMs, 0.0)\n| summarize\n    ['APIM overhead p50']    = round(percentile(apimOverheadMs,  50), 1),\n    ['APIM overhead p95']    = round(percentile(apimOverheadMs,  95), 1),\n    ['APIM overhead p99']    = round(percentile(apimOverheadMs,  99), 1),\n    ['Foundry inference p50']= round(percentile(foundryMs,       50), 1),\n    ['Foundry inference p95']= round(percentile(foundryMs,       95), 1),\n    ['Foundry inference p99']= round(percentile(foundryMs,       99), 1),\n    ['Total APIM p50']       = round(percentile(apimDurationMs,  50), 1),\n    ['Total APIM p95']       = round(percentile(apimDurationMs,  95), 1),\n    ['Total APIM p99']       = round(percentile(apimDurationMs,  99), 1)\n| project Stat = \"Latency (ms)\",\n    ['APIM overhead p50'], ['APIM overhead p95'], ['APIM overhead p99'],\n    ['Foundry inference p50'], ['Foundry inference p95'], ['Foundry inference p99'],\n    ['Total APIM p50'], ['Total APIM p95'], ['Total APIM p99']",
        "size": 1,
        "title": "Latency percentiles by layer (ms)",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
        ],
        "visualization": "table",
        "gridSettings": {
          "formatters": [
            { "columnMatch": "p50", "formatter": 8, "formatOptions": { "palette": "blue",   "min": 0, "max": 5000  } },
            { "columnMatch": "p95", "formatter": 8, "formatOptions": { "palette": "orange", "min": 0, "max": 15000 } },
            { "columnMatch": "p99", "formatter": 8, "formatOptions": { "palette": "red",    "min": 0, "max": 30000 } }
          ],
          "filter": false
        }
      },
      "name": "percentiles-table"
    },

    {
      "type": 1,
      "content": { "json": "## WAF Firewall Events\n\nAny request **blocked or matched** by the WAF (OWASP CRS 3.2 + Bot Manager). A high matched-but-allowed count may indicate false-positive rules worth tuning." },
      "name": "section-waf"
    },

    {
      "type": 3,
      "content": {
        "version": "KqlItem/1.0",
        "query": "AGWFirewallLogs\n| where TimeGenerated {TimeRange}\n| summarize\n    Blocked = countif(action_s == \"Blocked\"),\n    Matched = countif(action_s == \"Matched\"),\n    Total   = count()\n    by ruleSetType_s, ruleId_s, ruleGroup_s, message_s\n| sort by Blocked desc, Total desc\n| project\n    ['Rule Set']  = ruleSetType_s,\n    ['Rule ID']   = ruleId_s,\n    ['Rule Group']= ruleGroup_s,\n    Message       = message_s,\n    Blocked,\n    Matched,\n    Total",
        "size": 1,
        "title": "WAF rule matches / blocks",
        "queryType": 0,
        "resourceType": "microsoft.operationalinsights/workspaces",
        "crossComponentResources": [
          "/subscriptions/d201ebeb-c470-4a6f-82d5-c2f95bb0dc1e/resourceGroups/rg-contoso-ai-platform-dev/providers/Microsoft.OperationalInsights/workspaces/law-contoso-ai-dev"
        ],
        "visualization": "table",
        "gridSettings": {
          "formatters": [
